mapper.select:
SELECT l.id FROM slm_law l WHERE l.is_active=1 AND (
      INSTR(l.name,#{query}) > 0 OR EXISTS (
        SELECT 1 FROM slm_content c WHERE c.source_type=l.source_type AND c.external_id=l.external_id
          AND (INSTR(c.name,#{query}) > 0 OR INSTR(c.content,#{query}) > 0)
      )
    )
